<?php
session_start();
if (!isset($_SESSION['username'],$_SESSION['role']) || $_SESSION['role'] !== 'admin') { header('Location: /authenication/login/login.php'); exit(); }
require_once(__DIR__.'/../../../Database/db/db.php'); require_once(__DIR__.'/../../includes/csrf/csrf.php');
$pdo=get_db(); $token=generate_csrf_token(); $message=''; $messageType='success';
$instructors=$pdo->query("SELECT id,COALESCE(full_name,username) AS display_name FROM users WHERE role='instructor' AND status='active' ORDER BY display_name")->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['add_course'])) {
 if(!validate_csrf_token($_POST['csrf_token']??'')) {$message='Your session token expired. Refresh the page and try again.';$messageType='danger';}
 else {$title=trim($_POST['course_name']??'');$instructorId=filter_input(INPUT_POST,'instructor_id',FILTER_VALIDATE_INT);$description=trim($_POST['description']??'');$category=trim($_POST['category']??'');
  if($title===''||!$instructorId){$message='Course title and instructor are required.';$messageType='danger';}
  else {$check=$pdo->prepare("SELECT id FROM users WHERE id=? AND role='instructor' AND status='active'");$check->execute([$instructorId]);if(!$check->fetch()){$message='Choose an active instructor from the list.';$messageType='danger';}else{$insert=$pdo->prepare('INSERT INTO courses (title,description,category,instructor_id) VALUES (?,?,?,?)');$insert->execute([$title,$description,$category,$instructorId]);$message='Course created successfully.';}}
 }
}
$q=$pdo->query("SELECT c.id,c.title,c.category,c.created_at,COALESCE(u.full_name,u.username,'Unassigned') AS instructor,(SELECT COUNT(*) FROM enrollments e WHERE e.course_id=c.id) AS enrolled_count FROM courses c LEFT JOIN users u ON u.id=c.instructor_id ORDER BY c.created_at DESC LIMIT 8");$recent=$q->fetchAll();
$pageTitle = 'Add a course';
include(__DIR__.'/../../includes/header/header.php');include(__DIR__.'/../../includes/navbar/navbar.php');include(__DIR__.'/../../includes/sidebar/sidebar.php');
