<div class="row g-4"><div class="col-xl-5"><section class="card border-0"><div class="card-body p-4"><h2 class="h5 mb-1">Course details</h2><p class="text-muted small mb-4">Enter the basic information learners will see.</p><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($token,ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="add_course" value="1"><div class="mb-3"><label class="form-label" for="courseName">Course title</label><input class="form-control" id="courseName" name="course_name" maxlength="100" required></div><div class="mb-3"><label class="form-label" for="courseCategory">Category</label><input class="form-control" id="courseCategory" name="category" maxlength="50" placeholder="e.g. Technology"></div><div class="mb-3"><label class="form-label" for="courseInstructor">Instructor</label><select class="form-select" id="courseInstructor" name="instructor_id" required><option value="">Choose an instructor</option><?php foreach($instructors as $i):?><option value="<?=(int)$i['id']?>"><?=htmlspecialchars($i['display_name'],ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select><?php if(!$instructors):?><div class="form-text text-warning">Add an active instructor before creating a course.</div><?php endif;?></div><div class="mb-4"><label class="form-label" for="courseDescription">Description</label><textarea class="form-control" id="courseDescription" name="description" rows="5" placeholder="Describe the course"></textarea></div><div class="d-flex gap-2"><button class="btn btn-primary" type="submit" <?=$instructors?'':'disabled'?>>Create course</button><a class="btn btn-light" href="/Admin-dashboard/Courses/all_courses/all_courses.php">Cancel</a></div></form></div></section></div>
